select 'b3e91f6c47d2', m.mx + row_number() over (order by t.i), t.e->>'lib', t.e->'chunk'
  from jsonb_array_elements($kb$[{"lib": "field", "chunk": {"id": "fed-fmcsa-cdl-classes-1", "state": "US", "title": "When a crew truck needs a CDL: the 26,001 lb and 10,000 lb trailer rule (Class A, B, C)", "topic": "DOT rules for crew trucks: CDL, medical card, hours of service, inspections, loads", "text": "A commercial driver license (CDL) is needed by weight rating, not by what the truck looks like (49 CFR 383.5). Class A (combination): the truck and trailer together are rated or weigh 26,001 lb or more AND the trailer is rated or weighs more than 10,000 lb. Class B (heavy straight truck): the single truck is rated or weighs 26,001 lb or more, for example most tandem dump trucks and water trucks. Class C: smaller vehicles built for 16 or more people including the driver, or hauling placarded hazardous materials. The rule uses whichever is greater, the rating on the door tag (GVWR) or the real weight. The combination rating (GCWR) is the greater of the maker's number on the power unit's label or the truck GVWR plus the trailer GVWR. Worked example: a pickup tagged 14,000 lb GVWR pulling an equipment trailer tagged 14,000 lb is 28,000 lb combined with a trailer over 10,000 lb, so it is a Class A combination. The same pickup with a 9,900 lb trailer is 23,900 lb and needs no CDL. A 25,999 lb straight truck with a trailer of 10,000 lb or less needs no CDL either. States issue the license and may add their own rules, and some state exemptions exist, so check the state driver manual.", "source": "49 CFR 383.5 (definitions: commercial motor vehicle Groups A, B, C; GCWR; GVWR)", "url": "https://www.law.cornell.edu/cfr/text/49/383.5", "checked": "2026-11-20", "edition": "eCFR text as shown on law.cornell.edu, read 2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-us", "tier": "core"}},
{"lib": "field", "chunk": {"id": "fed-fmcsa-usdot-number-1", "state": "US", "title": "Does my work truck need a USDOT number on the door", "topic": "DOT rules for crew trucks: CDL, medical card, hours of service, inspections, loads", "text": "FMCSA says a company needs a USDOT number when it runs a vehicle in interstate commerce that has a weight rating or weight \"of 4,536 kg (10,001 pounds) or more, whichever is greater\" (truck alone or truck plus trailer), or carries placarded hazardous materials. Interstate means trade that crosses a state line, \"Between a place in a State and a place outside of such State\". For companies that stay inside one state, FMCSA lists the states that also require a USDOT number for in-state commercial trucks: AL, AK, AZ, CA, CO, CT, DE, FL, GA, HI, ID, IN, IA, KS, KY, ME, MD, MA, MI, MN, MO, MT, NE, NV, NJ, NY, NC, OH, OK, OR, PA, SC, TX, UT, WA, WV, WI, WY, plus Puerto Rico. Each of those states sets its own weight line for in-state trucks, so check with the state. A state not on the list may still have its own state number or permit. The number is free from FMCSA and is tied to the company, not to each truck. The list is from the FMCSA page as updated September 3, 2025.", "source": "FMCSA, \"Do I Need a USDOT Number?\" (page updated 2025-09-03); 49 CFR 390.5", "url": "https://www.fmcsa.dot.gov/registration/do-i-need-usdot-number", "checked": "2026-11-20", "edition": "FMCSA web page, last updated September 3, 2025", "confidence": "high", "kind": "summary", "license": "gov-us", "tier": "core"}},
{"lib": "field", "chunk": {"id": "fed-fmcsa-medical-card-1", "state": "US", "title": "DOT medical card: who needs one and how often (every 24 months)", "topic": "DOT rules for crew trucks: CDL, medical card, hours of service, inspections, loads", "text": "A driver of a commercial motor vehicle (10,001 lb or more in interstate commerce, with or without a CDL) must be medically examined and certified by a medical examiner. 49 CFR 391.45 requires a new exam for any driver who has not been certified \"during the preceding 24 months\". Some drivers are on a 12 month cycle instead: drivers with insulin-treated diabetes, drivers certified under the alternative vision standard, and drivers in an exempt intracity zone. A driver whose ability to do the job has been affected by an injury or illness must be examined again before driving, whatever the date on the card. A medical examiner can also write a card for less than 24 months to watch a condition such as high blood pressure. So the pipelayer who only drives the 1 ton with the equipment trailer needs a current medical card, not just the CDL drivers. These are the federal rules for trucks that cross state lines or carry interstate freight. A truck that never leaves the state follows that state's version, which is usually close but can have different weights or hours, so check with the state.", "source": "49 CFR 391.45 (persons who must be medically examined and certified); 49 CFR 390.5", "url": "https://www.law.cornell.edu/cfr/text/49/391.45", "checked": "2026-11-20", "edition": "eCFR text as shown on law.cornell.edu, read 2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-us", "tier": "core"}},
{"lib": "field", "chunk": {"id": "fed-fmcsa-eld-exempt-1", "state": "US", "title": "Electronic logs (ELD): which crew trucks do not need one", "topic": "DOT rules for crew trucks: CDL, medical card, hours of service, inspections, loads", "text": "FMCSA lists the drivers who do not have to use an electronic logging device (ELD): drivers using the short-haul exception (\"Drivers who use the short-haul, timecard exceptions are not required to keep records of duty status (RODS) or use ELDs.\"); drivers who have to keep a log on no more than 8 days in any 30 day period (they can use a paper log on those days); driveaway-towaway operations where the vehicle driven is the thing being delivered; and trucks \"manufactured before the model year 2000\". A crew truck that normally stays inside 150 air miles and gets back within the short-haul hours needs time cards, not an ELD. If that truck goes outside the exception more than 8 days in any 30, it needs an ELD. The FMCSA page was issued as guidance in 2018 and marked rescinded on March 10, 2022 only because the same rules are in the regulation itself (49 CFR 395.8 and Part 395 Subpart B); the regulation text was not re-read for this chunk.", "source": "FMCSA, \"Who is exempt from the ELD rule?\" (guidance 2018; 49 CFR 395.8(a)(1)(iii))", "url": "https://www.fmcsa.dot.gov/hours-service/elds/who-exempt-eld-rule", "checked": "2026-11-20", "edition": "FMCSA guidance page, 2018 (rule text: 49 CFR 395.8)", "confidence": "medium", "kind": "summary", "license": "gov-us", "tier": "core"}},
{"lib": "field", "chunk": {"id": "fed-fmcsa-annual-inspection-1", "state": "US", "title": "Annual DOT inspection: every truck AND trailer, proof on the vehicle", "topic": "DOT rules for crew trucks: CDL, medical card, hours of service, inspections, loads", "text": "49 CFR 396.17: \"Every commercial motor vehicle must be inspected as required by this section.\" In a combination each unit counts on its own: \"the tractor, semitrailer, and the full trailer (including the converter dolly if so equipped) must each be inspected.\" A commercial vehicle may not be used unless each part of it \"has passed an inspection in accordance with the terms of this section at least once during the preceding 12 months\" and \"documentation of such inspection is on the vehicle.\" The proof can be the inspection report itself or a sticker or decal showing the inspection date, who did it, the vehicle it belongs to, and that it passed. What crews miss: the equipment trailer and the tilt-deck need their own inspection and their own sticker, not just the truck. This applies from the 10,001 lb commercial vehicle line, not only to CDL trucks. A roadside officer will ask for the sticker or report on both units. These are the federal rules for trucks that cross state lines or carry interstate freight. A truck that never leaves the state follows that state's version, which is usually close but can have different weights or hours, so check with the state.", "source": "49 CFR 396.17(a)-(c); 49 CFR 396.21", "url": "https://www.law.cornell.edu/cfr/text/49/396.17", "checked": "2026-11-20", "edition": "eCFR text as shown on law.cornell.edu, read 2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-us", "tier": "core"}},
{"lib": "field", "chunk": {"id": "fed-fmcsa-cargo-check-1", "state": "US", "title": "Checking the load on the road: first 50 miles, then every 3 hours or 150 miles", "topic": "DOT rules for crew trucks: CDL, medical card, hours of service, inspections, loads", "text": "49 CFR 392.9: a commercial truck may not be driven unless the cargo is \"properly distributed and adequately secured\", and the \"tailgate, tailboard, doors, tarpaulins, spare tire and other equipment used in its operation\" are secured, and nothing blocks the driver's view or movement. The driver must make sure of that before driving, then \"Inspect the cargo and the devices used to secure the cargo within the first 50 miles after beginning a trip\" and adjust or add tie-downs as needed. After that, re-check whenever the driver changes duty status, or the truck \"has been driven for 3 hours\", or \"has been driven for 150 miles, whichever occurs first.\" For a crew this means: after loading the excavator, pipe, plates or a trench box, stop within the first 50 miles (chains and binders settle), and again at the fuel stop. Heavy equipment over 10,000 lb has its own tie-down rule (49 CFR 393.130: at least four tie-downs, see the library chunk on tying down equipment).", "source": "49 CFR 392.9(a)-(b); 49 CFR 393.130", "url": "https://www.law.cornell.edu/cfr/text/49/392.9", "checked": "2026-11-20", "edition": "eCFR text as shown on law.cornell.edu, read 2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-us", "tier": "core"}},
{"lib": "field", "chunk": {"id": "fed-fhwa-size-weight-1", "state": "US", "title": "Federal truck weight limits: 80,000 lb gross, 20,000 single axle, 34,000 tandem", "topic": "DOT rules for crew trucks: CDL, medical card, hours of service, inspections, loads", "text": "On the Interstate system and reasonable access to it, 23 CFR 658.17 sets the weight limits a state must allow without a special permit: \"The maximum gross vehicle weight shall be 80,000 pounds.\" One axle: 20,000 pounds. \"The maximum gross weight on tandem axles is 34,000 pounds.\" Groups of axles must also meet the bridge formula, W = 500 x (LN / (N - 1) + 12N + 36), where W is the weight allowed on the group, L is the distance in feet between the outer axles of the group, and N is the number of axles. Two sets of tandems may each carry 34,000 lb when the first and last axles are at least 36 ft apart. Anything heavier, such as a large excavator on a lowboy, moves on a state overweight permit, and the permit sets the route, the hours and the escorts. States also have their own limits on state and local roads, bridge postings, and seasonal (frost) load limits, which can be lower. Axle weights are what get a dump truck ticketed: a truck can be under its gross and still be over on the rear tandem if the load sits too far back.", "source": "23 CFR 658.17(a)-(e)", "url": "https://www.law.cornell.edu/cfr/text/23/658.17", "checked": "2026-11-20", "edition": "eCFR text as shown on law.cornell.edu, read 2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-us", "tier": "core"}},
{"lib": "field", "chunk": {"id": "spec-fl-dep-main-disinfection-1", "state": "FL", "title": "Florida bac-T rule for new water mains: two samples on separate days, 6 hours apart", "topic": "Disinfecting new water mains and repairs (AWWA C651): doses, sampling, cut-ins", "checked": "2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-state", "text": "Florida sets its own sampling rule for new and altered public water mains in Rule 62-555.340 of the state administrative code (Department of Environmental Protection). Disinfection must follow \"AWWA Standard C651, C652, or C653\" (C651 is the one for water mains). Then, at each sampling location, the rule requires \"a total of at least two samples - each taken on a separate day and taken at least six hours apart from the other sample(s)\". If any sample shows total coliform, sampling goes on \"until two consecutive samples at each sampling location show the absence of total coliform.\" The sampling locations are the ones called for in the AWWA standard (for mains: along the line at set spacing, at the end, and on branches). So in this state the two sets cannot both be pulled the same day, even though the 2014 edition of AWWA C651 has an option for two sets 15 minutes apart after the main sits 16 hours. The main cannot be placed in service until the department or county health unit clears it based on the results. The rule text read was last amended August 28, 2003; check with the permitting office for any newer requirement in the construction permit.", "source": "Fla. Admin. Code R. 62-555.340 (amended 8-28-03); read 2026-11-20", "url": "https://www.law.cornell.edu/regulations/florida/Fla-Admin-Code-Ann-R-62-555-340", "edition": "Rule 62-555.340 as amended 8-28-03", "effective": "2003-08-28", "tier": "core"}}]$kb$::jsonb) with ordinality t(e, i),
       (select max(ord) as mx from pb_ai.kb_chunks where version = 'b3e91f6c47d2') m
 where not exists (select 1 from pb_ai.kb_chunks k where k.version = 'b3e91f6c47d2' and k.chunk->>'id' = t.e->'chunk'->>'id');

-- the version's row count (the Ask loader refuses a library whose rows don't match kb_versions.n)
update pb_ai.kb_versions v
   set n = c.n, counts = c.counts
  from (select sum(k)::int as n, jsonb_object_agg(lib, k) as counts
          from (select lib, count(*)::int as k from pb_ai.kb_chunks where version = 'b3e91f6c47d2' group by lib) x) c
 where v.version = 'b3e91f6c47d2';
